    "shrinksTheTextEncoder4a0g2": "Уменьшает текстовый энкодер, чтобы сэкономить память, ценой части качества изображения. «По умолчанию» оставляет выбор модели: для Qwen-Image 2.1 это её опубликованный FP8-энкодер (8,75 ГБ вместо 16,3); выберите Dense (bf16), чтобы зафиксировать выпущенный энкодер. FP8 (storage) — безопасный выбор и единственный, который работает с выгрузкой на CPU. FP8 (compute) требует RTX 40-й серии или новее.{p1} О том, что именно было применено, сообщает загруженная сборка ниже.",
