    "cPUOffloadstfxl": "Выгрузка на CPU",
    "removeImageavuyc": "Удалить изображение {p1}",
    "thisModelTakesAdditionalk6w2l": "Этой модели требуется {p1} доп. изображени{p2} здесь. Удалите{p3} {p4}, чтобы сгенерировать.",
    "addImagevoafl": "Добавить изображение {p1}",
    "theResolutionEveryInput23f9v": "Разрешение, к которому приводится (по площади) каждое входное изображение перед тем, как его прочитает модель. Отдельно от размера вывода: высокое сохраняет больше деталей из входов и стоит больше памяти и времени на каждое изображение. High (2048) с множеством изображений требует большой GPU.",
    "2KPresets6mjdl": "Пресеты 2K",
    "chooseDownloadOnlyTomk7r7": "Выберите «Только скачать», чтобы подготовить выбранную модель и её обязательные файлы без загрузки. Относится к следующей выбранной модели; прогресс и отмена видны в разделе «Загрузки».",
    "autoPicksPerModelcj51v": "Auto выбирает по модели: GGUF компилируется при загрузке; плотная модель держит первые два изображения точно и eager, а компилирует начиная с третьего (~2x дальше). eager = слитые ядра без компиляции. default/max добавляют torch.compile (max также TF32 + слитый QKV и кэш шага на моделях с 20+ шагами).",
    "howTheModelComputesmvpsc": "Как считает модель. Auto выбирает самую быструю точность, которую поддерживает железо (INT8 на любой способной GPU, затем FP8, если карта её имеет), и квантует трансформер на низкоточные тензорные ядра. Выбор GGUF достигает этого загрузкой ПОЛНОЙ базовой модели вместо GGUF и возвращается к GGUF как есть, если устройство, VRAM или диск этого не позволяют; официальная сборка уже плотная и квантуется на месте, с откатом к обычному BF16. Off запускает чекпоинт как есть.",
    "attentionKernelAutoUpgradescor8d": "Ядро внимания. Auto переходит на слитое внимание cuDNN на NVIDIA, когда активен скоростной профиль. sage — это INT8-внимание (SageAttention 2; без локальной установки Studio берёт сборку из Hugging Face kernels-hub, которая работает на GPU Ampere, Ada и Hopper, а любое другое GPU оставляет по умолчанию): быстро (10-40%), но может затемнять кадры у некоторых семейств (Qwen, Wan), поэтому включается никогда автоматически.",
    "autoMeasuresFreeVRAMxr0mg": "auto измеряет свободную VRAM. fast держит всё в памяти. balanced потоково загружает трансформер. low_vram выгружает каждый компонент (минимум VRAM, медленнее).",
    "whichCardThisModelv0m39": "На какой карте запускается эта модель. Auto берёт устройство, на которое указывает torch, а на смешанной машине это не обязательно самая большая карта. Модель изображений не делится между картами, поэтому это один выбор, а не пул.",
    "staticSkipExtrapolatesMiddlegbdcv": "Static skip экстраполирует средние шаги по фиксированному расписанию (12+ шагов) и сохраняет компиляцию и CUDA-граф. Auto включает его для текст-в-изображение, при числе шагов не ниже измеренного, на моделях, где он оставался близок к полному рендеру: Qwen-Image, Qwen-Image-2.1, FLUX.1 Krea dev, FLUX.2 klein base 4B на любом скоростном уровне кроме Off/Eager, а FLUX.1 dev и HunyuanImage 2.1 только на Max. First-Block-Cache переиспользует хвост трансформера между шагами (~1.4x, цена по качеству выше); Auto включает его для других многошаговых моделей только на Max. LAiM_DIFFUSION_AUTO_STEP_SKIP=0 не даёт Auto выбирать Static skip.",
    "cancelLoadnxvsd": "Отменить загрузку",
    "theImageToUpscalewnnv1": "Изображение для апскейла. Оно увеличивается в указанное число раз, затем детализируется в более высоком разрешении по вашему промпту; описывайте в промпте то же содержание.",
    "howMuchNewDetailqic8r": "Сколько новых деталей добавлять при апскейле. Низкое сохраняет изображение верным оригиналу; высокое добавляет больше (и может увести в сторону). 0.35 — хороший hires-fix по умолчанию.",
    "aReferenceTheModelwkl6g": "Референс, на который модель опирается (объект, стиль или композиция), генерируя НОВОЕ изображение по вашему промпту в размере ниже. В отличие от Transform, это не перерисовка этого изображения, поэтому силы правки нет.",
    "theImageToEditbzcnu": "Изображение для правки. Опишите изменение в инструкции ниже; добавьте другие изображения, чтобы объединить их, и обращайтесь к ним как Image 2, Image 3 и т. д.",
    "pointTheEditAtvskh0": "Указывает правке на область. Это направляет генеративную правку: модель перерисовывает всё изображение и просит изменить помеченную область, поэтому пиксели вне неё не гарантированно останутся теми же.",
