    "colourAnnotationsx001m": "Цветные аннотации",
    "separateMaskImage2x8pdp": "Отдельная маска (Image 2)",
    "matchImage1Keeps787y5": "Match Image 1 сохраняет пропорции источника при выбранном размере. Custom использует соотношения сторон и разрешение ниже. Показан именно тот размер, который будет сгенерирован.",
    "matchImage15d3k7": "Как изображение 1",
    "styleOrCharacterAdapterspo5z2": "Стилевые или персонажные адаптеры поверх модели. Введите id репозитория Hugging Face (или выберите предложение) и задайте силу (1.0 = полный эффект, 0 = выключено). Можно накладывать несколько.",
    "conditionTheImageOnzu552": "Условная генерация по контрольной карте (границы / глубина / позы). Union-модели покрывают много типов. Используйте \"Canny\", чтобы выделить границы вашего изображения, или \"Passthrough\", если это уже контрольная карта.",
    "controlType6wu6w": "Тип контрольной карты",
    "controlsHowStronglyThef6ms0": "Насколько строго модель следует промпту. Начните со значения по умолчанию для выбранной модели; дистиллированные модели могут требовать низкий или нулевой guidance.",
    "howEachDenoisingSteprq8zj": "Как выполняется каждый шаг денуазинга. Model default сохраняет планировщик, с которым модель поставляется. Сообщественные чекпоинты часто называют свой, например DPM++ 2M с Karras.",
