    "savesAResumePointj2p87": "Сохранять точку восстановления каждые столько шагов, чтобы сбой или выключение можно было продолжить с того же места. 0 выключает это; остановка и сохранение всегда оставляют точку в любом случае.",
    "rendersPreviewImagesWithv8zts": "Рендерит превью с теми же промптами и сидами каждые столько шагов, чтобы видеть, когда LoRA уже изучила объект и когда начинает переобучаться. 0 выключает; каждый раунд добавляет несколько секунд.",
    "howManyOfThosekfq4z": "Сколько таких контрольных точек остаётся на диске; старые удаляются по мере сохранения новых. Увеличьте, чтобы сравнивать ранние шаги. 0 сохраняет все.",
