    "offSquareCrop3c5m0": "Выкл (квадратный кроп)",
    "mirrorsImagesLeftRighta4f12": "Случайно зеркалит изображения по горизонтали для большего разнообразия. Не включайте для текста, логотипов и объектов с односторонними чертами (пробор, шрам); включите для стилей и симметричных объектов.",
    "onMirrorImagespclg9": "Вкл (зеркалить изображения)",
    "theChanceEachImage8mk6o": "Вероятность того, что каждое изображение будет обучено с пустым промптом вместо подписи. 0.05–0.1 помогает LoRA реагировать на guidance (CFG), не переобучаясь на точной подписи; 0 выключает.",
    "randomlyDropsPartOfc0ire": "Случайно отключает часть входа LoRA на каждом шаге — слабая защита от запоминания маленького набора данных. Обычно выбирают 0 (выключено); попробуйте 0.05–0.1, если результаты слишком копируют обучающие изображения.",
    "whichNoiseLevelsTrainingnmv3a": "На каких уровнях шума обучение проводит свои шаги. Default следует собственному расписанию модели (Qwen-Image и LTX-2 совпадают с тем, чем они генерируют). Custom задаёт сдвиг напрямую: выше — композиция и раскладка, ниже — мелкие детали.",
