    "trainAnothero4ywf": "Обучить другую",
    "stopTrainingbj9ow": "Остановить обучение?",
    "continueTrainingv7j4z": "Продолжить обучение",
    "createGeneratesImagesTrain1ijgn": "«Создание» генерирует изображения. «Обучение» настраивает диффузионный LoRA на ваших собственных картинках. Рабочие процессы из боковой панели — правка, инпейнт, расширение, апскейл — выполняются в «Создании».",
    "aCozyWoodenCabinyofs4": "Уютный деревянный домик на заснеженной горе в сумерках, из окон льётся тёплый свет, сосны и тихо падает снег. Кинематографичное фото, мягкий золотистый свет.",
