    "parallelSlotsz0w70": "Параллельные слоты",
    "speculativeDecoding4giro": "Спекулятивное декодирование",
    "fasterGenerationAutoUses6u130": "Более быстрая генерация. Auto берёт первый кэшированный драфтер (MTP-голову или ассистента, затем DFlash2, DFlash, DSpark, EAGLE-3), подстраивает длину черновика под эту машину и черновит, только пока это быстрее. Выберите вид, чтобы forced. Каждый драфтер также копирует повторяющийся текст; Ngram копирует без него. Драфтеры читаются из локального кэша Hugging Face, никогда не скачиваются.",
    "draftTokenskrjcr": "Токены черновика",
    "kVCacheDtype5i4gx": "Тип KV-кэша",
    "lowerKVCachePrecision85vry": "Понизьте точность KV-кэша, чтобы сэкономить память, ценой части качества. Auto держит полную точность; 8-bit — самый безопасный шаг вниз. TurboQuant лучше держит качество на низких разрядностях и добавляет 3.5-bit, где 3-битные ключи лежат рядом с 4-битными значениями; скользящее окно и рекуррентные слои при этом сохраняют родной кэш.",
    "int8Prefillt3ypl": "Int8 префилл",
    "lowerKVCachePrecisioni0f9j": "Пониженная точность KV-кэша экономит VRAM ценой качества. f16 — по умолчанию; q8_0…iq4_nl квантованы.",
    "fasterGenerationAutoPicksyqp17": "Более быстрая генерация. Auto выбирает лучшую стратегию для модели и платформы, либо выберите её принудительно. DSpark и DFlash скачивают sidecar-драфтер (около 11 ГБ и 1.5 ГБ) и обменивают VRAM на скорость; MTP и ngram результат не меняют.",
    "kVCachePrecisionForingjp": "Точность KV-кэша для собственного контекста черновой модели, отдельно от KV Cache Dtype выше. f16 — по умолчанию; квантование экономит VRAM на драфтере, который целевая модель всё равно проверяет.",
