    "addAudioi7933": "Добавить аудио {p1}",
    "widthAndHeightInxb815": "Ширина и высота в пикселях, с шагом {p1}. Модель обучена на {p2}; другие размеры сохраняют примерно то же число пикселей и могут снизить качество.",
