    "loadingTheModelThisihhbt": "Загрузка модели. Возможно, скачается и базовая модель.",
    "generationSettingsw26ni": "Параметры генерации",
    "autoMeasuresFreeVRAMxr0mg": "auto измеряет свободную VRAM. fast держит всё в памяти. balanced потоково загружает трансформер. low_vram выгружает каждый компонент (минимум VRAM, медленнее).",
    "autoCompilesEveryModel5mn6e": "Auto компилирует каждую модель при загрузке: клип денуазится минуты, поэтому однократная компиляция всегда окупается внутри одного запуска. eager = слитые ядра без компиляции. max добавляет TF32 + слитый QKV и кэш шага на моделях с 20+ шагами.",
    "howTheModelComputesec4iz": "Как считает модель. Auto выбирает самую быструю точность, которую поддерживает железо (INT8 на любой способной GPU, затем FP8, если карта её имеет), квантуя трансформер на низкоточные тензорные ядра, и оставляет обычный bf16, если устройство или план памяти этого не позволяют. Off всегда считает в bf16.",
    "fullPipelineModelsOnlyjfkj2": "Только модели с полным пайплайном",
    "attentionKernelAutoUpgradescor8d": "Ядро внимания. Auto переходит на слитое внимание cuDNN на NVIDIA, когда активен скоростной профиль. sage — это INT8-внимание (SageAttention 2; без локальной установки Studio берёт сборку из Hugging Face kernels-hub, которая работает на GPU Ampere, Ada и Hopper, а любое другое GPU оставляет по умолчанию): быстро (10-40%), но может затемнять кадры у некоторых семейств (Qwen, Wan), поэтому включается никогда автоматически.",
    "whichCardThisModeltksig": "На какой карте запускается эта модель. Auto берёт устройство, на которое указывает torch, а на смешанной машине это не обязательно самая большая карта. Видео-модель не делится между картами, поэтому это один выбор, а не пул.",
    "staticSkipExtrapolatesMiddlec3l3k": "Static skip экстраполирует средние шаги по фиксированному расписанию (12+ шагов) и сохраняет компиляцию и CUDA-граф; Wan2.2 A14B и LTX-2 идут без кэша. Auto включает его для текст-в-видео (без ключевых кадров и референсов), при числе шагов не ниже измеренного, на Wan2.2 TI2V 5B на любом скоростном уровне кроме Off/Eager, и на HunyuanVideo 1.5 и MiniMax-H3 только на Max. First-Block-Cache переиспользует хвост трансформера между шагами (цена по качеству выше); Auto включает его для других многошаговых моделей только на Max. LAiM_DIFFUSION_AUTO_STEP_SKIP=0 не даёт Auto выбирать Static skip.",
    "clearAllVideos13kes": "Очистить все видео?",
    "textAndFramesc2vly": "Текст и кадры",
    "cancelLoadnxvsd": "Отменить загрузку",
    "startFramefkner": "Начальный кадр",
    "endFramekrt47": "Конечный кадр",
    "lockTheClipTo98y47": "Привязывает клип к персонажу, стилю, движению, движению камеры или голосу. Называйте их в промпте тегами ниже -- \"use the cat from <Picture 1>, match the shot rhythm of <Video 1>\" -- потому что модель читает их по порядку. Не более 9 изображений, 3 видео и 3 аудиозаписей, всего 12. Аудио требует к себе изображение или видео.",
    "picture97ysg": "Изображение {p1}",
    "removePicture0li2i": "Удалить изображение {p1}",
