    "audiowwdxv": "Аудио {p1}",
    "howReferencePicturesAregaaxx": "Как размерны референсные изображения. Match оставляет их при собственной площади клипа. Max кодирует их на 2048 пикселей для более сильного сходства и проходит с ними каждый шаг сэмплинга, поэтому может быть в разы медленнее.",
